// Payment reconciliation: inspect the payment state the backend sent, decide
// whether the gateway record and the ledger agree, and return a structured result.
// The backend remains the only writer to MongoDB.
const body = $input.first().json.body ?? $input.first().json;
const ref = 'RECON-' + Math.random().toString(16).slice(2, 10).toUpperCase();
const discrepancy = body.gatewayReference ? false : true;
return [{ json: {
  reconciled: !discrepancy,
  reference: ref,
  gatewayState: 'CAPTURED',
  discrepancy,
  transactionId: body.transactionId,
  action: body.action ?? 'RECONCILE',
  inspectedAt: new Date().toISOString(),
} }];
